import{_ as a,C as c,o as t,c as E,a2 as r,b as i,w as d,a as s,E as A,a7 as l}from"./chunks/framework.ClrTBeVd.js";const b=JSON.parse('{"title":"ui-forge 项目架构","description":"","frontmatter":{"title":"ui-forge 项目架构","outline":"deep","publish":true},"headers":[],"relativePath":"ai/ui-forge-project-architecture.md","filePath":"ai/ui-forge-project-architecture.md","lastUpdated":1790144657000}'),n={name:"ai/ui-forge-project-architecture.md"};function B(p,e,u,h,f,g){const o=c("Mermaid");return t(),E("div",null,[e[1]||(e[1]=r('<h1 id="ui-forge-项目架构" tabindex="-1">ui-forge 项目架构 <a class="header-anchor" href="#ui-forge-项目架构" aria-label="Permalink to &quot;ui-forge 项目架构&quot;">​</a></h1><h2 id="项目定位" tabindex="-1">项目定位 <a class="header-anchor" href="#项目定位" aria-label="Permalink to &quot;项目定位&quot;">​</a></h2><p>代码仓库：<a href="https://github.com/hyy215/ui-forge" target="_blank" rel="noreferrer">hyy215/ui-forge</a>。本文基于 2026-09-22 的提交 <a href="https://github.com/hyy215/ui-forge/tree/4fbf47d" target="_blank" rel="noreferrer">4fbf47d</a> 讲解。</p><p>ui-forge 面向 React + TypeScript 中后台项目，支持从 MasterGo 设计链接、参考图和需求生成页面，提供 VS Code 插件页面和命令行（CLI）两个入口。</p><p>ui-forge 复用 Codex 的会话和执行能力，不另建一套执行引擎。Codex 负责读设计、查代码、编码和验证，ui-forge 负责将这些能力接入开发环境，让用户能够提交任务、查看执行过程、处理审批，并从不同入口继续同一个任务。</p><h2 id="任务如何流转" tabindex="-1">任务如何流转 <a class="header-anchor" href="#任务如何流转" aria-label="Permalink to &quot;任务如何流转&quot;">​</a></h2><p>页面和 CLI 连接同一个 ui-forge 本地服务（Agent Server），由它统一管理 Codex App Server 进程、会话和审批。在页面中创建的任务，也可以通过 CLI 继续。只要本地服务和对应的 Codex 进程仍在运行，关闭页面或退出 CLI 就不会主动停止任务。读取设计、修改代码和操作浏览器，则由 Codex 调用相应工具完成。</p><p>下面从用户提交任务开始，沿着请求和回复看一次完整交互。图中的“项目与工具”合并表示目标项目文件、终端、设计工具和浏览器。</p>',8)),(t(),i(l,null,{default:d(()=>[A(o,{id:"mermaid-24",class:"mermaid",graph:"%25%25%7Binit%3A%20%7B%22sequence%22%3A%20%7B%22width%22%3A%20110%2C%20%22actorMargin%22%3A%2025%2C%20%22wrap%22%3A%20true%2C%20%22mirrorActors%22%3A%20false%7D%7D%7D%25%25%0AsequenceDiagram%0A%20%20participant%20entry%20as%20%E9%A1%B5%E9%9D%A2%E6%88%96%20CLI%0A%20%20participant%20server%20as%20%E6%9C%AC%E5%9C%B0%E6%9C%8D%E5%8A%A1%0A%20%20participant%20codex%20as%20Codex%0A%20%20participant%20tools%20as%20%E9%A1%B9%E7%9B%AE%E4%B8%8E%E5%B7%A5%E5%85%B7%0A%20%20entry-%3E%3Eserver%3A%20%E6%8F%90%E4%BA%A4%E4%BB%BB%E5%8A%A1%E8%BE%93%E5%85%A5%0A%20%20server-%3E%3Eserver%3A%20%E6%A3%80%E6%9F%A5%E5%B9%B6%E5%87%86%E5%A4%87%E7%8E%AF%E5%A2%83%0A%20%20server-%3E%3Ecodex%3A%20%E5%88%9B%E5%BB%BA%E4%BC%9A%E8%AF%9D%EF%BC%8C%E5%90%AF%E5%8A%A8%E6%9C%AC%E8%BD%AE%0A%20%20codex-%3E%3Etools%3A%20%E8%AF%BB%E5%8F%96%E8%AE%BE%E8%AE%A1%E5%92%8C%E4%BB%A3%E7%A0%81%0A%20%20tools--%3E%3Ecodex%3A%20%E8%BF%94%E5%9B%9E%E8%AF%BB%E5%8F%96%E7%BB%93%E6%9E%9C%0A%20%20codex-%3E%3Etools%3A%20%E4%BF%AE%E6%94%B9%E7%9B%AE%E6%A0%87%E9%A1%B9%E7%9B%AE%0A%20%20codex--%3E%3Eserver%3A%20%E8%BF%9B%E5%BA%A6%E4%B8%8E%E6%96%87%E4%BB%B6%E5%8F%98%E6%9B%B4%0A%20%20server--%3E%3Eentry%3A%20%E6%9B%B4%E6%96%B0%E4%BB%BB%E5%8A%A1%E5%B1%95%E7%A4%BA%0A%20%20opt%20%E9%9C%80%E8%A6%81%E5%AE%A1%E6%89%B9%E6%97%B6%0A%20%20%20%20codex-%3E%3Eserver%3A%20%E5%8F%91%E5%87%BA%E5%AE%A1%E6%89%B9%E8%AF%B7%E6%B1%82%0A%20%20%20%20server-%3E%3Eentry%3A%20%E5%B1%95%E7%A4%BA%E5%BE%85%E5%AE%A1%E6%89%B9%E6%93%8D%E4%BD%9C%0A%20%20%20%20entry-%3E%3Eserver%3A%20%E7%94%A8%E6%88%B7%E5%90%8C%E6%84%8F%E6%88%96%E6%8B%92%E7%BB%9D%0A%20%20%20%20server-%3E%3Ecodex%3A%20%E6%A0%A1%E9%AA%8C%E5%B9%B6%E5%9B%9E%E4%BC%A0%E5%86%B3%E8%AE%AE%0A%20%20end%0A%20%20codex-%3E%3Etools%3A%20%E6%A3%80%E6%9F%A5%E4%BB%A3%E7%A0%81%E4%B8%8E%E9%A1%B5%E9%9D%A2%0A%20%20tools--%3E%3Ecodex%3A%20%E8%BF%94%E5%9B%9E%E6%A3%80%E6%9F%A5%E7%BB%93%E6%9E%9C%0A%20%20codex--%3E%3Eserver%3A%20%E6%80%BB%E7%BB%93%E4%B8%8E%E6%9C%AC%E8%BD%AE%E7%BB%93%E6%9D%9F%E9%80%9A%E7%9F%A5%0A%20%20server--%3E%3Eentry%3A%20%E5%B1%95%E7%A4%BA%E6%89%A7%E8%A1%8C%E7%BB%93%E6%9E%9C%0A"})]),fallback:d(()=>[...e[0]||(e[0]=[s(" Loading... ",-1)])]),_:1})),e[2]||(e[2]=r('<p>进度会随执行持续上报，审批也可能发生在任意需要授权的操作前，并不限于图中的位置。具体验证和修复由 D2C Skill（任务指导与配套脚本）及规则引导，不是本地服务按固定步骤调度。</p><p>最终代码留在目标项目，页面和 CLI 展示的是执行记录与结果。<strong>本轮结束不等于验收通过</strong>：交付说明仍要区分已验证、失败、未验证和受阻的内容。用户继续提出修改时，沿同一条路径发送输入；运行中补充给当前轮次，空闲时在原会话中启动新一轮。</p><h2 id="关键设计" tabindex="-1">关键设计 <a class="header-anchor" href="#关键设计" aria-label="Permalink to &quot;关键设计&quot;">​</a></h2><p>创建任务时，ui-forge 根据设计来源配置工具，并将设计规则和工程规范交给 Codex。何时读取设计、修改哪些文件、如何验证，由 Codex 结合需求和现有项目决定。</p><p>会话历史由 Codex 保存。ui-forge 通过任务索引关联目标项目、设计绑定和会话，并保存图片附件和诊断等辅助数据。重新打开任务时，ui-forge 读取历史并衔接后续消息；本地服务重启后则重新加载会话。加载会话本身不会启动新一轮执行，后续修改仍需用户发起。</p><h2 id="实现参考" tabindex="-1">实现参考 <a class="header-anchor" href="#实现参考" aria-label="Permalink to &quot;实现参考&quot;">​</a></h2><details class="details custom-block"><summary>代码模块与职责</summary><table tabindex="0"><thead><tr><th>模块</th><th>主要职责</th></tr></thead><tbody><tr><td><code>agent-webview</code></td><td>设计输入、任务时间线、审批、规则编辑和诊断展示</td></tr><tr><td><code>vscode-extension</code></td><td>承载 Webview，绑定当前工作区并转发请求</td></tr><tr><td><code>agent-cli</code></td><td>命令行输入输出、任务列表、继续和停止</td></tr><tr><td><code>agent-server</code></td><td>托管 Codex 进程，维护任务索引、连接、事件和设计绑定</td></tr><tr><td><code>codex-client</code></td><td>读取配置和规则，启动 Codex，校验原生请求与事件</td></tr><tr><td><code>client-core</code></td><td>消费消息流，将快照和后续事件合并成展示状态</td></tr><tr><td><code>shared-protocol</code></td><td>定义 ui-forge 各入口与 Server 之间的通信格式</td></tr></tbody></table><p>Webview 通过 Extension 访问本地服务，CLI 直接连接本地服务，使用 HTTP 与 NDJSON 消息流；本地服务通过 <code>codex-client</code>，使用标准输入输出上的 JSONL 与 Codex App Server 通信。NDJSON 和 JSONL 都按行传送 JSON 消息。</p><p>本文版本中，ui-forge 客户端与 Server 的通信协议为 22。它与 Codex 原生协议是两层协议；原生消息使用生成的 Schema（数据结构校验规则）验证。</p></details><details class="details custom-block"><summary>Codex 接口与 ui-forge 命令速查</summary><p>RPC 是通过方法名和参数发起调用、再接收结果的通信方式。下面列的是本项目使用的 Codex App Server 原生接口，不是 ui-forge 自己实现的会话引擎。</p><table tabindex="0"><thead><tr><th>方法</th><th>用途</th></tr></thead><tbody><tr><td><code>initialize</code></td><td>建立连接后握手，提交客户端信息和能力声明</td></tr><tr><td><code>config/read</code></td><td>读取配置，检查 MCP、Agent 等运行设置</td></tr><tr><td><code>skills/extraRoots/set</code></td><td>把 ui-forge 自带的 D2C Skill 注册给 Codex</td></tr><tr><td><code>account/read</code></td><td>检查登录信息；本项目调用时不刷新登录凭据</td></tr><tr><td><code>thread/start</code></td><td>创建一个新的 Codex 会话，返回 <code>thread.id</code></td></tr><tr><td><code>thread/resume</code></td><td>把已有会话装载到当前连接，不重放旧输入，也不启动新轮次</td></tr><tr><td><code>thread/read</code></td><td>读取会话快照和历史；页面恢复、状态查看和诊断都会用到</td></tr><tr><td><code>thread/list</code></td><td>查找主线程下的子线程，补充诊断报告</td></tr><tr><td><code>turn/start</code></td><td>在会话中启动新一轮，传入文字、图片，并附加临时产物目录说明</td></tr><tr><td><code>turn/steer</code></td><td>给正在运行的轮次补充输入，不创建新的轮次</td></tr><tr><td><code>turn/interrupt</code></td><td>停止指定的运行中轮次</td></tr></tbody></table><p>通信还有另外两个方向：Codex 会推送进度通知，也会发出需要回复的请求。</p><table tabindex="0"><thead><tr><th>类型</th><th>原生方法</th><th>ui-forge 怎么处理</th></tr></thead><tbody><tr><td>会话和轮次通知</td><td><code>thread/started</code>、<code>thread/status/changed</code>、<code>turn/started</code>、<code>turn/completed</code></td><td>更新展示状态</td></tr><tr><td>执行项和用量通知</td><td><code>item/*</code>、<code>thread/tokenUsage/updated</code></td><td>展示过程，记录用量观测</td></tr><tr><td>操作审批</td><td><code>item/commandExecution/requestApproval</code>、<code>item/fileChange/requestApproval</code>、<code>item/permissions/requestApproval</code></td><td>展示操作范围，校验并回传用户决议</td></tr><tr><td>提问和表单</td><td><code>item/tool/requestUserInput</code>、<code>mcpServer/elicitation/request</code></td><td>收集回答，按对应格式回复</td></tr></tbody></table><p>通知不需要用户回应；审批、提问和表单是服务端请求，要用原始 request ID 回传结果。</p><p>终端里的 <code>ui-forge</code> 子命令是项目自己的入口，和上述原生接口不是一回事：</p><ul><li><code>run</code> 创建任务，<code>list</code> 列出任务，<code>status</code> 读取快照。</li><li><code>resume</code> 连接原任务，并在空闲时发送继续请求；不等于只调用 <code>thread/resume</code>。</li><li><code>diagnostics</code> 输出诊断，<code>design-check</code> 只读检查设计接入。</li><li><code>doctor</code> 检查 Codex 版本和登录状态，<code>serve</code> 启动本地服务。</li></ul></details><p><a href="https://github.com/hyy215/ui-forge/blob/4fbf47d/apps/agent-server/src/sessions/sessionService.ts" target="_blank" rel="noreferrer">sessionService.ts</a> 负责会话操作，<a href="https://github.com/hyy215/ui-forge/blob/4fbf47d/packages/codex-client/src/codexClient.ts" target="_blank" rel="noreferrer">codexClient.ts</a> 负责原生通信适配；两层协议分别见 <a href="https://github.com/hyy215/ui-forge/tree/4fbf47d/packages/shared-protocol/src" target="_blank" rel="noreferrer">shared-protocol</a> 和生成的 <a href="https://github.com/hyy215/ui-forge/blob/4fbf47d/packages/codex-client/src/generated/native.ts" target="_blank" rel="noreferrer">NativeMethods</a>。</p><p>文中的任务工作方式和交付要求见 <a href="https://github.com/hyy215/ui-forge/blob/4fbf47d/packages/codex-client/.agents/skills/ui-forge-d2c/SKILL.md" target="_blank" rel="noreferrer">D2C Skill</a>。</p>',10))])}const m=a(n,[["render",B]]);export{b as __pageData,m as default};
